function Status({ status }) {
  if (status === "loading") return <p>Loading…</p>;
  if (status === "error") return <p role="alert">Could not load.</p>;
  return <p>Ready.</p>;
}

function CourseCard({ title }) {
  return <article><h2>{title}</h2><StartButton /></article>;
}
function StartButton() { return <button>Start lesson</button>; }

const states = {
  empty: { disabled: true, message: "Write an answer" },
  ready: { disabled: false, message: "Ready to submit" },
  saving: { disabled: true, message: "Saving…" },
};
